import 'dart:convert';

import 'package:flutter/services.dart' show rootBundle;

/// Maps GBIF taxon keys to built-in catalog species, and supplies the
/// order-level whitelist used to filter the occurrence query.
///
/// Both come from `assets/data/species_gbif_keys.json`, generated by
/// `tool/generate_species_gbif_keys.dart`. Deriving the whitelist from the
/// catalog makes it complete by construction: no catalog species can be
/// filtered out, and birds, insects and terrestrial plants are excluded
/// because none appear in the catalog.
class SpeciesCatalogMatcher {
  final Map<int, String> _byGbifKey;
  final List<int> _orderKeys;

  const SpeciesCatalogMatcher._(this._byGbifKey, this._orderKeys);

  static SpeciesCatalogMatcher? _cached;

  static Future<SpeciesCatalogMatcher> load() async {
    final cached = _cached;
    if (cached != null) return cached;

    final raw = await rootBundle.loadString(
      'assets/data/species_gbif_keys.json',
    );
    return _cached = fromJsonString(raw);
  }

  /// Visible for testing so the matcher can be built without an asset bundle.
  static SpeciesCatalogMatcher fromJsonString(String raw) {
    final json = jsonDecode(raw) as Map<String, dynamic>;
    final keys = (json['speciesKeys'] as Map).map(
      (k, v) => MapEntry(int.parse(k as String), v as String),
    );
    final orders = (json['orderKeys'] as List).cast<int>();
    return SpeciesCatalogMatcher._(keys, List.unmodifiable(orders));
  }

  /// Clears the cache. Testing only.
  static void resetCache() => _cached = null;

  String? localIdFor(int gbifKey) => _byGbifKey[gbifKey];

  List<int> get orderKeys => _orderKeys;
}
